34:     public SaveRequest ToRequest(long? id) => new(new StudentDraft {
35:         StudentNo=StudentNo, StudentName=StudentName, StudentNameKana=StudentNameKana,
36:         BirthDateInput=BirthDateInput ?? new(), GenderCode=GenderCode, PostalCode=PostalCode,
37:         PrefectureCode=PrefectureCode, AddressLine1=AddressLine1, AddressLine2=AddressLine2,
38:         PhoneNumber=PhoneNumber, EmailAddress=EmailAddress, AdmissionDate=AdmissionDate,
39:         EnrollmentStatusCode=EnrollmentStatusCode, EnrollmentEndDate=EnrollmentEndDate,
40:         ClassId=IdParser.Optional(ClassId,"REG-018"), EmergencyContactName=EmergencyContactName,
41:         RelationshipCode=RelationshipCode, EmergencyPhoneNumber=EmergencyPhoneNumber, Remarks=Remarks
42:     },id,id.HasValue ? IdParser.Required(ExpectedVersion,"REG-INT-013") : EnsureNewVersion(),SchoolYear,GradeCode,DuplicateToken,OperationReason);
43:     private long? EnsureNewVersion() { if (!string.IsNullOrEmpty(ExpectedVersion)) throw new WebFault(400,"要求が不正です。"); return null; }
44:     public static StudentSaveInput From(StudentDetail? detail, string? contextId, LookupSet lookups)
45:     {
46:         var d=detail?.Draft ?? new StudentDraft(); var cls=lookups.Classes.FirstOrDefault(c=>c.ClassId==d.ClassId);
47:         return new() { StudentNo=d.StudentNo,StudentName=d.StudentName,StudentNameKana=d.StudentNameKana,
48:             BirthDateInput=detail is null ? new() : JapaneseDateService.ToInput(detail.BirthDate),GenderCode=d.GenderCode,
49:             PostalCode=d.PostalCode,PrefectureCode=d.PrefectureCode,AddressLine1=d.AddressLine1,AddressLine2=d.AddressLine2,
50:             PhoneNumber=d.PhoneNumber,EmailAddress=d.EmailAddress,AdmissionDate=d.AdmissionDate,
51:             EnrollmentStatusCode=d.EnrollmentStatusCode,EnrollmentEndDate=d.EnrollmentEndDate,ClassId=d.ClassId?.ToString(CultureInfo.InvariantCulture),
52:             EmergencyContactName=d.EmergencyContactName,RelationshipCode=d.RelationshipCode,EmergencyPhoneNumber=d.EmergencyPhoneNumber,
53:             Remarks=d.Remarks,SchoolYear=cls?.SchoolYear ?? (detail is null ? WebPresentation.SchoolYear : null),GradeCode=cls?.GradeCode,
54:             ExpectedVersion=detail?.RowVersion.ToString(CultureInfo.InvariantCulture),ReturnContextId=contextId };
55:     }
56: }
57: public static class IdParser
58: {
59:     public static long Required(string? raw,string field) => Optional(raw,field) ?? throw new WebFault(422,"識別番号・版を正しく指定してください。",field);
60:     public static long? Optional(string? raw,string field) { if(string.IsNullOrEmpty(raw)) return null; if(raw.Length>19 || raw.Any(c=>c<'0'||c>'9') || !long.TryParse(raw,NumberStyles.None,CultureInfo.InvariantCulture,out var n)||n<=0) throw new WebFault(422,"識別番号・版を正の64bit整数で指定してください。",field); return n; }
61: }
