25:         Outcome.Saved=>("I-STU-001","保存しました。"), Outcome.NoChange=>("I-STU-004","変更はありません。"),
26:         Outcome.ConfirmationRequired=>("W-STU-101","同一人物の候補があります。確認してください。"),
27:         Outcome.ValidationFailed=>("E-COM-004","入力を確認してください。"),Outcome.Forbidden=>("E-COM-004","この操作を実行する権限がありません。"),
28:         Outcome.NotFound=>("E-COM-004","対象は存在しません。"),Outcome.Conflict=>("E-COM-004","データが変更されています。再読込してください。"),
29:         Outcome.Unknown=>("E-COM-004","処理結果が不明です。再送せず検索して確認してください。"),_=>("E-COM-004","処理を完了できませんでした。") };
